parameters.jsCode:
const payload = $json;
const filesystems = Array.isArray(payload.filesystems) ? payload.filesystems : [];
const timestamp = payload.timestamp ?? new Date().toISOString();
const summary = payload.summary ?? {};

// Limiares: preferir os do Health Agent (fonte única em disk_capacity.py).
// Fallback local apenas se o agent não enviar thresholds.
const THRESHOLDS = payload.thresholds ?? {
  warning: 70,
  error: 85,
  critical: 95,
};

function formatFree(bytes) {
  const n = Number(bytes);
  if (!Number.isFinite(n) || n < 0) return 'espaço livre desconhecido';
  const TB = 1024 ** 4;
  const GB = 1024 ** 3;
  if (n >= TB) return `${(n / TB).toFixed(2)} TB livres`;
  if (n >= GB) return `${(n / GB).toFixed(0)} GB livres`;
  return `${Math.max(1, Math.round(n / (1024 ** 2)))} MB livres`;
}

function mountLabel(mount) {
  if (mount === '/') return 'NVMe raiz /';
  if (mount === '/srv/storage') return `Storage ${mount}`;
  return `Storage ${mount}`;
}

function stateFromPercent(usedPercent) {
  if (usedPercent >= Number(THRESHOLDS.critical)) return 'critical';
  if (usedPercent >= Number(THRESHOLDS.error)) return 'error';
  if (usedPercent >= Number(THRESHOLDS.warning)) return 'warning';
  return 'normal';
}

function thresholdForState(state) {
  if (state === 'critical') return Number(THRESHOLDS.critical);
  if (state === 'error') return Number(THRESHOLDS.error);
  if (state === 'warning') return Number(THRESHOLDS.warning);
  return 0;
}

const EVENT_BY_STATE = {
  warning: 'disk_capacity_warning',
  error: 'disk_capacity_error',
  critical: 'disk_capacity_critical',
  normal: 'disk_capacity_normal',
};

const ACTION_BY_STATE = {
  warning: 'Revisar crescimento e arquivos recentes.',
  error: 'Planejar liberação de espaço e identificar maiores consumidores.',
  critical: 'Priorizar análise imediata antes de novos downloads/backups.',
  normal: null,
};

const items = [];

for (const fs of filesystems) {
  const mount = String(fs?.mount ?? '').trim();
  if (!mount) continue;

  const usedPercent = Number(fs.used_percent ?? 0);
  const capacityState =
    fs.capacity_state && fs.capacity_state !== 'unknown'
      ? String(fs.capacity_state).toLowerCase()
      : stateFromPercent(usedPercent);

  const unavailable = fs.available === false;
  let severity = 'info';
  let event = 'disk_capacity_normal';
  let status = 'healthy';
  let shouldEmit = false;
  let requiresAttention = false;
  let suggestedAction = null;
  let message = `${mountLabel(mount)} em utilização normal (${usedPercent}%).`;

  if (unavailable) {
    severity = 'error';
    event = 'disk_capacity_error';
    status = 'active';
    shouldEmit = true;
    requiresAttention = true;
    message = `Filesystem ${mount} indisponível para medição de capacidade.`;
    suggestedAction =
      'Verificar se o mount está acessível. Não executar remount/fsck automaticamente.';
  } else if (capacityState === 'critical') {
    severity = 'critical';
    event = EVENT_BY_STATE.critical;
    status = 'active';
    shouldEmit = true;
    requiresAttention = true;
    message =
      `${mountLabel(mount)} atingiu ${usedPercent}% de utilização. ` +
      'Espaço disponível em nível crítico.';
    suggestedAction = ACTION_BY_STATE.critical;
  } else if (capacityState === 'error') {
    severity = 'error';
    event = EVENT_BY_STATE.error;
    status = 'active';
    shouldEmit = true;
    requiresAttention = true;
    message =
      `${mountLabel(mount)} atingiu ${usedPercent}% de utilização. ` +
      `Restam ${formatFree(fs.free_bytes)}.`;
    suggestedAction = ACTION_BY_STATE.error;
  } else if (capacityState === 'warning') {
    severity = 'warning';
    event = EVENT_BY_STATE.warning;
    status = 'active';
    shouldEmit = true;
    requiresAttention = true;
    message =
      `${mountLabel(mount)} atingiu ${usedPercent}% de utilização. ` +
      `Restam ${formatFree(fs.free_bytes)}.`;
    suggestedAction = ACTION_BY_STATE.warning;
  } else {
    severity = 'info';
    event = EVENT_BY_STATE.normal;
    status = 'healthy';
    shouldEmit = false;
    requiresAttention = false;
    message = `${mountLabel(mount)} em utilização normal (${usedPercent}%).`;
    suggestedAction = null;
  }

  items.push({
    json: {
      should_emit: shouldEmit,
      source: 'disk_capacity',
      severity,
      component: 'filesystem',
      event,
      status,
      timestamp,
      message,
      details: {
        mount,
        device: fs.device ?? null,
        filesystem: fs.filesystem ?? null,
        total_bytes: fs.total_bytes ?? 0,
        used_bytes: fs.used_bytes ?? 0,
        free_bytes: fs.free_bytes ?? 0,
        used_percent: usedPercent,
        free_percent: fs.free_percent ?? null,
        total_gb: fs.total_gb ?? null,
        used_gb: fs.used_gb ?? null,
        free_gb: fs.free_gb ?? null,
        threshold: thresholdForState(capacityState),
        capacity_state: capacityState,
        previous_capacity_state: null,
        thresholds: THRESHOLDS,
        available: fs.available !== false,
        summary,
        notification_reason: null,
      },
      requires_attention: requiresAttention,
      suggested_action: suggestedAction,
    },
  });
}

return items;

const allItems = $input.all();
const results = [];

const severityRank = {
  info: 1,
  warning: 2,
  error: 3,
  critical: 4,
};

const capacityRank = {
  normal: 0,
  warning: 1,
  error: 2,
  critical: 3,
  unknown: 2,
};

// Decisão de downgrade:
// CRITICAL→ERROR ou ERROR→WARNING NÃO gera notificação (silencioso).
// Motivo: evitar spam por oscilação pequena entre faixas altas.
// Só notifica recuperação completa (qualquer faixa → normal) ou escalada.
const NOTIFY_ON_DEESCALATION = false;

for (const item of allItems) {
  const data = item.json;

  const previousEvent = data.previous_event ?? null;
  const previousSeverity = data.previous_severity ?? null;
  const previousStatus = data.previous_status ?? null;

  let previousDetails = data.previous_details ?? null;
  if (typeof previousDetails === 'string') {
    try {
      previousDetails = JSON.parse(previousDetails);
    } catch (e) {
      previousDetails = null;
    }
  }

  const previousCapacityState =
    previousDetails?.capacity_state ??
    (previousEvent === 'disk_capacity_critical'
      ? 'critical'
      : previousEvent === 'disk_capacity_error'
        ? 'error'
        : previousEvent === 'disk_capacity_warning'
          ? 'warning'
          : previousEvent === 'disk_capacity_recovered' || previousStatus === 'healthy'
            ? 'normal'
            : null);

  const currentCapacityState = data.details?.capacity_state ?? 'unknown';

  const details = {
    ...(data.details ?? {}),
    previous_capacity_state: previousCapacityState,
  };

  let shouldNotify = false;
  let reason = 'no_change';
  let out = null;

  // 1. PRIMEIRO INCIDENTE (cruzou faixa de atenção)
  if (previousEvent === null && data.should_emit === true) {
    shouldNotify = true;
    reason = 'first_incident';
  }

  // 2. RECUPERAÇÃO TOTAL (qualquer incidente → normal)
  else if (
    data.event === 'disk_capacity_normal' &&
    previousEvent !== null &&
    previousEvent !== 'disk_capacity_recovered' &&
    previousStatus !== 'healthy' &&
    previousCapacityState !== 'normal'
  ) {
    const mount = details.mount ?? 'filesystem';
    const label = mount === '/' ? 'NVMe raiz /' : `Storage ${mount}`;
    out = {
      ...data,
      should_emit: true,
      severity: 'info',
      event: 'disk_capacity_recovered',
      status: 'healthy',
      message:
        `${label} voltou a utilização normal (${details.used_percent}%). ` +
        `Estado anterior: ${previousCapacityState ?? previousEvent}.`,
      requires_attention: false,
      suggested_action:
        'Nenhuma ação imediata necessária. Continuar monitorando o crescimento do disco.',
      details: {
        ...details,
        capacity_state: 'normal',
        notification_reason: 'recovered',
      },
      notification: {
        should_notify: true,
        reason: 'recovered',
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,
        previous_capacity_state: previousCapacityState,
      },
    };
  }

  // 3. ESCALADA DE FAIXA / SEVERIDADE
  else if (
    data.should_emit === true &&
    previousEvent !== null &&
    previousEvent !== 'disk_capacity_recovered'
  ) {
    const currentRank = capacityRank[currentCapacityState] ?? severityRank[data.severity] ?? 0;
    const previousRank =
      capacityRank[previousCapacityState] ?? severityRank[previousSeverity] ?? 0;

    if (currentRank > previousRank) {
      shouldNotify = true;
      reason = 'severity_escalated';
    } else if (currentRank < previousRank) {
      // Downgrade entre faixas de alerta — silencioso por padrão
      reason = 'severity_deescalated';
      shouldNotify = NOTIFY_ON_DEESCALATION;
    } else if (data.event !== previousEvent && currentRank === previousRank) {
      shouldNotify = true;
      reason = 'incident_changed';
    } else {
      reason = 'no_change';
      shouldNotify = false;
    }
  }

  // 4. Normal contínuo sem histórico relevante
  else if (data.should_emit !== true) {
    reason = 'no_change';
    shouldNotify = false;
  }

  if (out === null) {
    details.notification_reason = reason;
    out = {
      ...data,
      details,
      notification: {
        should_notify: shouldNotify,
        reason,
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,
        previous_capacity_state: previousCapacityState,
      },
    };
  }

  results.push({ json: out });
}

return results;

parameters.jsonBody:
={{
{
  source: $json.source,
  severity: $json.severity,
  component: $json.component,
  event: $json.event,
  status: $json.status,
  timestamp: $json.timestamp,
  message: $json.message,
  details: {
    ...$json.details,
    notification_reason: $json.notification?.reason ?? $json.details?.notification_reason ?? null
  },
  requires_attention: $json.requires_attention,
  suggested_action: $json.suggested_action
}
}}
